      "mainEntity": [
        {
          "@type": "Question",
          "name": "Why is there a sulfur shortage?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Most sulfur is a leftover from refining oil and processing natural gas, so the supply depends on how much fuel is processed, not on the price of sulfur. The trade publisher CRU estimated that the world used about 1.9 million tons more sulfur than it made in 2025. In March 2026 the war closed the Strait of Hormuz, the route for close to half of the sulfur that moves by sea."
          }
        },
        {
          "@type": "Question",
          "name": "How much have sulfur prices gone up?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "The average value of U.S. sulfur exports rose from $77 a metric ton in January 2024 to $956 in August 2026, a rise of 1,146%. It was already $503 in February 2026, the last full month before the war."
          }
        },
        {
          "@type": "Question",
          "name": "Why is fertilizer so expensive?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Sulfur is used to make the sulfuric acid that turns phosphate rock into DAP and MAP, the two main phosphate fertilizers. At August 2026 export prices, the sulfur needed for a ton of DAP cost about $382, close to half of the $794 the fertilizer sold for. In January 2024 it was about $31."
          }
        },
        {
          "@type": "Question",
          "name": "What is sulfur used for?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "About 90% of the sulfur used in the United States is turned into sulfuric acid, according to the U.S. Geological Survey. Most of that acid goes to phosphate fertilizer. It is also used to pull copper, nickel and cobalt out of ore."
          }
        }
      ]
    }
